/**
 * Public view for a system-generated FAST Code that nobody has registered
 * or claimed.
 *
 * The daily FAST Code job and the slot seed mark those rows with
 * `fast_code_updates.created_by` of "system" or "daily-job" (and a
 * `fast_code_status` / prepared-slot row). An eBook `autoGenerated` flag is
 * not this signal: claimed books, including RM22, are marked that way too.
 */

export const SYSTEM_FAST_CODE_ACTORS = ["system", "daily-job"] as const;

export type SystemFastCodeActor = (typeof SYSTEM_FAST_CODE_ACTORS)[number];

export function isSystemFastCodeActor(createdBy: string | null | undefined): boolean {
  const value = createdBy?.trim().toLowerCase() || "";
  return (SYSTEM_FAST_CODE_ACTORS as readonly string[]).includes(value);
}

export type SystemFastCodeAccessInput = {
  /** Assigned by the daily job or the system slot seed. */
  systemGenerated: boolean;
  /** Paid activation, a build request, an account, or a registration. */
  registeredOrClaimed: boolean;
  /** Signed-in agent, admin, or prospect-gate session. */
  agentAccess: boolean;
};

/**
 * Brokers of a new system FAST Code get the public Mapsite only.
 * Registered or claimed owners, and agents, keep the full account.
 */
export function restrictSystemFastCodeFeatures(input: SystemFastCodeAccessInput): boolean {
  return input.systemGenerated && !input.registeredOrClaimed && !input.agentAccess;
}

/** Owner-only destinations that must not appear on that public home page. */
export function isOwnerOnlyPersonalHomeHref(href: string | null | undefined): boolean {
  const path = (href || "").trim().split("?")[0]?.split("#")[0] || "";
  if (!path.startsWith("/")) return false;
  return (
    path === "/talispros/mapsite" ||
    path.startsWith("/talispros/mapsite/") ||
    path === "/talispros/demo-mapsite" ||
    path.startsWith("/talispros/demo-mapsite/") ||
    path.startsWith("/talispros/mapsites/") ||
    path.startsWith("/admin") ||
    path.startsWith("/chat") ||
    path.startsWith("/crm")
  );
}

/** Closest zoom that still shows a building. Matches the map engine ceiling. */
export const PERSONAL_HOME_MAP_MIN_ZOOM = 3;
export const PERSONAL_HOME_MAP_MAX_ZOOM = 20;

export function stepPersonalHomeMapZoom(current: number, delta: number): number {
  const base = Number.isFinite(current) ? current : 9;
  const next = Math.round(base + delta);
  return Math.min(PERSONAL_HOME_MAP_MAX_ZOOM, Math.max(PERSONAL_HOME_MAP_MIN_ZOOM, next));
}

/**
 * Flag card inside the left-column map. Stays clear of the top-right zoom
 * buttons and of the pin at the centre.
 */
export function personalHomeFlagFrame(
  mapWidth: number,
  mapHeight: number,
): { width: number; centerX: number; top: number; height: number } {
  const zoomRail = 72;
  const width = Math.max(200, Math.min(352, Math.max(0, mapWidth - zoomRail - 16)));
  const rawCenter = mapWidth / 2;
  const overflow = rawCenter + width / 2 - (mapWidth - zoomRail);
  const centerX = rawCenter - Math.max(0, overflow);
  const top = 56;
  const tipY = mapHeight / 2 - 40;
  const bottom = Math.max(top + 160, tipY - 12);
  const height = Math.min(340, Math.max(160, bottom - top));
  return { width, centerX, top, height };
}
